parameters.jsCode:
const t = $('When Executed by Another Workflow').first().json.tournaments[0];
const aiOutput = $('AI Agent1').first().json.output;

const validRounds = ["R16", "R32", "R64", "R128"];
const roundMapping = {
  "R128": {
    "Qualification": "Qualifying",
    "R128": "R1",
    "R64": "R2",
    "R32": "R3",
    "R16": "R4",
    "QF": "Quarter Final",
    "SF": "Semi Final",
    "Final": "Final"
  },
  "R64": {
    "Qualification": "Qualifying",
    "R64": "R1",
    "R32": "R2",
    "R16": "R3",
    "QF": "Quarter Final",
    "SF": "Semi Final",
    "Final": "Final"
  },
  "R32": {
    "Qualification": "Qualifying",
    "R32": "R1",
    "R16": "R2",
    "QF": "Quarter Final",
    "SF": "Semi Final",
    "Final": "Final"
  },
  "R16": {
    "Qualification": "Qualifying",
    "R16": "R1",
    "QF": "Quarter Final",
    "SF": "Semi Final",
    "Final": "Final"
  }
};

const normalizeRound = r => {
  if (r.startsWith("Qual")) return "Qualification";
  if (r === "QF") return "Quarter Final";
  if (r === "SF") return "Semi Final";
  if (r === "Final") return "Final";
  return r;
};

return aiOutput.map(item => {
  const rawRound = item.round.startsWith("Qual.") ? "Qualification" : item.round;
  const normalized = normalizeRound(rawRound);

  // 🔹 mode 可能是 "MD-U19"、"WS U19"、"MSU19" 等，先抽取主要模式
  const mode = item.mode.trim();
  const baseMode = mode.replace(/[-\s]?U\d+/i, ""); // 移除 "-U19" 或 " U19"

  // 🔹 先試完整模式，再試 base 模式
  const maxRound = t.mode_max_round?.[mode] || t.mode_max_round?.[baseMode] || "";

  // 🔹 只有在 maxRound 有值且屬於 validRounds 時才做 mapping
  let mapRound = validRounds.includes(maxRound)
    ? (roundMapping[maxRound][rawRound] || normalized)
    : normalized;

  // 🔹 當 maxRound 沒值且 mapRound 是 "Qualification"，改成 "Qualifying"
  if (!maxRound && mapRound === "Qualification") {
    mapRound = "Qualifying";
  }

  // 🔹 將 item.round 轉成大寫且去掉空格
  const roundClean = item.round.replace(/\s+/g, '').toUpperCase();


  return {
    ...item,
    round: roundClean,
    max_round: maxRound || "",
    map_round: mapRound,
    league_id: t.league_id,
    league_name: t.league_name,
    league_level: t.level,
    age_category: t.age_category
  };
});

const input = $input.all(); // 取得輸入
const output = [];

for (const item of input) {
    const files = item.json.files;
    if (!files) continue;

    // files 是 object，遍歷每個 key-value
    for (const [filename, html] of Object.entries(files)) {
        output.push({
            json: {
                filename,   // 檔名
                html        // HTML 內容
            }
        });
    }
}

return output;

const allItems = $input.all(); // 取得所有輸入 items
const flattened = [];

for (const item of allItems) {
  if (item.json.output && Array.isArray(item.json.output)) {
    flattened.push(...item.json.output); // 展平每個 output
  }
}

// 回傳展平後的 item 陣列
return flattened;

const inputText = $input.first().json.data || '';
let outputs = [];

if (!inputText || typeof inputText !== 'string') {
  return outputs;
}

const lines = inputText.split(/\r?\n/);
const startsRegex = /\b\d{1,2}:\d{2}\s*(AM|PM)\b/i;

let startIdx = 0; // 本場比賽的開始 index
let matches = [];

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];

  if (startsRegex.test(line)) {
    if (startIdx < i) {
      // match_text 結束在「時間行的下一行」
      const endIdx = Math.min(i + 3, lines.length);
      const matchText = lines.slice(startIdx, endIdx).join('\n').trim();
      matches.push(matchText);
    }
    startIdx = i + 3; // 新一場比賽從這行開始
  }
}

// 處理最後一場
if (startIdx < lines.length) {
  const matchText = lines.slice(startIdx, lines.length).join('\n').trim();
  matches.push(matchText);
}

// 每10個 match_text 合併成一個物件
const groupSize = 5;
for (let i = 0; i < matches.length; i += groupSize) {
  const chunk = matches.slice(i, i + groupSize).join('\n\n'); 
  outputs.push({ json: { 
    today_date: $input.first().json.gmt8_today_date,
    match_city: $input.first().json.city,
    match_country: $input.first().json.country,
    match_timezone: $input.first().json.timezone,
    match_IANA_timezone: $input.first().json.IANA_timezone,
    match_text: chunk 
  } });
}

return outputs;

const modeMapping = {
  "MS": "Men Singles",
  "MD": "Men Doubles",
  "WS": "Women Singles",
  "WD": "Women Doubles",
  "XD": "Mixed Doubles"
};

return $input.all().map(item => {
  const data = item.json;

  // 取 mode 前兩個字母作為 key
  const modeKey = data.mode.trim().substring(0, 2).toUpperCase();

  return {
    ...data,
    map_mode: modeMapping[modeKey] || data.mode  // 找不到就保留原本 mode
  };
});

return $input.all().map(item => {
  const data = item.json;
  const local_datetime = data.local_datetime; // e.g. 2025-10-22T10:00:00+02:00

  const IANA_tz = data.IANA_timezone;
  const dt = DateTime.fromISO(local_datetime, { zone: IANA_tz });

  // 轉成 UTC
  const utc = dt.setZone('UTC+8');

  return {
    ...data,
    // 去掉毫秒，保留 ISO 時間格式
    datetime: utc.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ"), // e.g. 2025-10-22T08:00:00+00:00
  };
});

const t = $input.first().json.tournaments[0];
const html_list = [];

// 取得 GMT+8 今天日期
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Taipei' });

// 若沒有輸入資料
if (!t) {
  return [{}];
}

// today_html
if (t.today_html) {
  html_list.push({ 
    city: t.city || "",
    country: t.country || "",
    IANA_timezone: t.IANA_timezone || "",
    gmt8_today_date: today,
    html: t.today_html
  });
}

// tomorrow_html
if (t.tomorrow_html) {
  html_list.push({ 
    city: t.city || "",
    country: t.country || "",
    IANA_timezone: t.IANA_timezone || "",
    gmt8_today_date: today,
    html: t.tomorrow_html
  });
}

return html_list;

// 從上一個節點取得所有比賽資料
const input = $input.all().map(item => item.json);

// 轉換成你要的格式
const events = input.map(match => {

  const utcTime = new Date(match.datetime).toISOString();

  return {
    kickoffTime: utcTime,
    court: match.court,
    round: match.round,
    currentRound: match.map_round,
    isActive: true,
    status: false,
    leagueId: match.league_id,
    leagueName: match.league_name,
    mode: match.map_mode,
    maxRound: match.max_round,
    levelName: match.league_level,
    playerHome1Name: match.home_player1,
    playerHome1Country: match.home_country1,
    playerHome2Name: match.home_player2,
    playerHome2Country: match.home_country2,
    playerAway1Name: match.away_player1,
    playerAway1Country: match.away_country1,
    playerAway2Name: match.away_player2,
    playerAway2Country: match.away_country2
  };

});

return { json: { events } };
